console.log('Timestamp ya hany:', webhook.json.query.timestamp);
console.log('Full webhook data:', JSON.stringify(webhook.json, null, 2));

return items;

const inputItem = items.length > 0 ? items[0] : {};
const item = inputItem.json || {};

// Extract AI response text from different possible formats
let aiText = '';

// New OpenAI node format: output[0].content[0].text
if (item.output?.[0]?.content?.[0]?.text) {
  aiText = item.output[0].content[0].text;
}
// Old OpenAI format: choices[0].message.content
else if (item.choices?.[0]?.message?.content) {
  const content = item.choices[0].message.content;
  aiText = Array.isArray(content) ? content.map(p => p.text || p.content || '').join('\n').trim() : content;
}
// Fallback formats
else if (item.message?.content) {
  aiText = item.message.content;
} else if (item.text) {
  aiText = item.text;
} else {
  aiText = JSON.stringify(item);
}

console.log('=== AI RAW RESPONSE ===');
console.log(aiText);

// Clean and parse JSON
const cleanJson = aiText.replace(/```json\s*|```/g, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(cleanJson);
  console.log('=== PARSED AI RESPONSE ===');
  console.log(JSON.stringify(parsed, null, 2));
} catch (e) {
  console.error('Failed to parse AI response:', e.message);
  parsed = { error: 'Failed to parse JSON', raw: aiText, input_keys: Object.keys(item) };
}

// Get webhook query params
let webhookQuery = {};
try {
  const webhookData = $('Webhook').first();
  webhookQuery = webhookData ? webhookData.json.query : {};
} catch (e) {
  webhookQuery = { error: e.message };
}

const paymentId = webhookQuery.payment_id ? parseInt(webhookQuery.payment_id, 10) : null;
const userId = webhookQuery.user_id ? parseInt(webhookQuery.user_id, 10) : null;
const expectedAmount = webhookQuery.expected_amount ? parseFloat(webhookQuery.expected_amount) : 0;

return {
  json: {
    ...parsed,
    payment_id: paymentId,
    user_id: userId,
    original_amount: expectedAmount,
    confidence_score: parsed.confidence_score || 0,
    recommendation: parsed.recommendation || 'reject',
    reason: parsed.reason || 'No reason provided',
    extracted_data: parsed.extracted_data || {},
    debug_webhook: webhookQuery,
  }
};

// Prepare the exact payload for Laravel
const data = items[0].json;
const payload = {
  payment_id: data.payment_id,
  confidence_score: data.confidence_score,
  recommendation: data.recommendation,
  reason: data.reason || 'No reason provided',
  extracted_data: data.extracted_data || {},
  analysis_json: data,
};
console.log('Final payload to Laravel:', JSON.stringify(payload, null, 2));
return [{ json: { payload } }];
